import Foundation
import Testing

@testable import Honorum

/// The shared contract fixtures in `contracts/fixtures`, generated by the web
/// client. The Rust server and this app read the same fixtures.
@Suite("Shared contract fixtures")
struct FixtureTests {
    private static func fixture(_ name: String) throws -> JSON {
        let root = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
        let data = try Data(contentsOf: root.appending(path: "contracts/fixtures/\(name)"))
        return try #require(JSON.decode(data))
    }

    @Test("Document merges agree with the web client")
    func merge() throws {
        for c in try Self.fixture("merge.json").list("cases") {
            let name = Comment(rawValue: c.text("name"))
            let result = JSON.merge(base: c["base"] ?? .null, local: c["local"] ?? .null, remote: c["remote"] ?? .null)
            #expect(result.body == c["body"], name)
            #expect(result.conflicted == c.flag("conflicted"), name)
        }
    }

    @Test("Calendar feeds parse like the web client")
    func icalendar() throws {
        let fixture = try Self.fixture("icalendar.json")
        let timeZone = try #require(TimeZone(identifier: fixture.text("timezone")))
        for c in fixture.list("cases") {
            let name = Comment(rawValue: c.text("name"))
            let now = try #require(ISO8601.date(from: c.text("now")))
            let tasks = ICalendar.tasks(from: c.text("text"), feed: "fixture", label: c.text("label"), now: now, timeZone: timeZone)
            let expected = c.list("expected")
            #expect(tasks.count == expected.count, name)
            for (task, want) in zip(tasks, expected) {
                #expect(task.uid == want.text("uid"), name)
                #expect(task.title == want.text("title"), name)
                #expect(task.course == want.text("course"), name)
                #expect(task.done == want.flag("done"), name)
                #expect((task.url ?? "") == want.text("url"), name)
                #expect(ISO8601.date(from: task.due) == ISO8601.date(from: want.text("due")), name)
            }
        }
    }
}
